// Parse Slack slash command: /task create [title] #[project] [P0..P3]
//
// Slack signs `v0:<timestamp>:<raw body>`, so the signature is checked over the exact
// bytes Slack sent. Behind a Webhook v2 with `rawBody: true`, n8n 2.12.3 delivers them
// in the `data` binary property and never as `$json.rawBody` (#1712, lesson-467), and
// parses the form into `$json.body`. No bytes means nothing to verify, so nothing is
// trusted: rebuilding the form from the parsed body is deliberately not a fallback,
// because an encoder's choices (`~` vs `%7E`) do not survive the round trip.
const crypto = require('crypto');
let raw = null;
try {
  raw = await this.helpers.getBinaryDataBuffer(0, 'data');
} catch (e) {
  raw = null;
}
const body = (typeof $json.body === 'object' && $json.body !== null) ? $json.body : {};

const headers = $json.headers || {};
const rawText = (body.text || '').trim();
const responseUrl = body.response_url || '';
const userName = body.user_name || 'slack-user';

// Slack signature verification: strictly fail-closed
const slackSig = headers['x-slack-signature'] || '';
const slackTs = headers['x-slack-request-timestamp'] || '';
const slackSecret = $env.SLACK_SIGNING_SECRET || '';
let isValidSlack = false;

if (slackSecret && slackSig && slackTs && raw && raw.length > 0) {
  const timeDiff = Math.abs(Math.floor(Date.now() / 1000) - Number(slackTs));
  if (timeDiff <= 300) {
    const base = Buffer.concat([Buffer.from(`v0:${slackTs}:`, 'utf8'), raw]);
    const expected = Buffer.from('v0=' + crypto.createHmac('sha256', slackSecret).update(base).digest('hex'), 'utf8');
    const given = Buffer.from(String(slackSig), 'utf8');
    isValidSlack = given.length === expected.length && crypto.timingSafeEqual(given, expected);
  }
}

if (!isValidSlack) {
  return [{
    json: {
      isValidSlack: false,
      ackMessage: '❌ Invalid or expired Slack request signature.'
    }
  }];
}

const parts = rawText.split(/\s+/);
let action = parts[0]?.toLowerCase() || 'create';
let remaining = action === 'create' ? parts.slice(1) : parts;

let project = 'kubelab';
let priority = 'P2';
const titleWords = [];

for (const word of remaining) {
  if (word.startsWith('#')) {
    project = word.substring(1);
  } else if (['P0', 'P1', 'P2', 'P3'].includes(word.toUpperCase())) {
    priority = word.toUpperCase();
  } else {
    titleWords.push(word);
  }
}

const title = titleWords.join(' ') || 'Untitled Task';
const priorityMap = { 'P0': 4, 'P1': 3, 'P2': 2, 'P3': 1 };

return [{
  json: {
    title: title,
    project: project,
    priority: priority,
    priorityNum: priorityMap[priority] || 2,
    responseUrl: responseUrl,
    userName: userName,
    isValidSlack: isValidSlack,
    ackMessage: `⏳ Creating task *${title}* in project _#${project}_ (priority: ${priority})...`
  }
}];

// Resolve target project ID from search or default to 1
const projects = Array.isArray($json) ? $json : ($json.data || []);
const command = $('Parse Slack Command').first().json;
let projectId = 1;

const match = projects.find(p => p.title?.toLowerCase() === command.project?.toLowerCase() || p.identifier?.toLowerCase() === command.project?.toLowerCase());
if (match && match.id) {
  projectId = match.id;
}

return [{
  json: {
    ...command,
    projectId: projectId
  }
}];
